import java.util.*;public class Driver {record Item(String id,String name,double price){Item{if(id==null||id.isBlank()||price<0)throw new IllegalArgumentException("Invalid item");}}static class Inventory{List<Item> items=new ArrayList<>();void add(Item i){items.add(Objects.requireNonNull(i));}List<Item> all(){return List.copyOf(items);}}public static void main(String[]a){Inventory i=new Inventory();i.add(new Item("IT01","Laptop",65000));i.add(new Item("IT02","Mouse",1200));System.out.println("Total Items in Inventory: "+i.all().size());i.all().forEach(System.out::println);}}
